package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Boolean;
    in attribute io_1 : Real;
    in attribute io_2 : Real;
    attribute sampleCount : Integer := 0;
    attribute previousPressed : Boolean := false;
    perform action tick {
      first start;
      then if ((io_0) and ((not previousPressed))) {
        first start;
        then assign sampleCount := sampleCount + 1;
      }
      then assign previousPressed := io_0;
    }
    out attribute io_3 : Integer = (if ((sampleCount - 5 * RealFunctions::floor(sampleCount / 5)) == (0)) ? 1000 else 0);
    out attribute serial_0_trigger : Boolean = (if ((io_0) and ((not previousPressed))) ? true else false);
    out attribute serial_0_value_0 : Real = io_1;
    out attribute serial_0_value_1 : Real = io_2;
    out attribute serial_0_value_2 : Integer = sampleCount;
  }
  part system : Controller;
}
